class Solution:
    def countTriplesInBand(self, values: List[int], low: int, high: int) -> int:
        n, count = len(values), 0
        for i in range(n):
            for j in range(i + 1, n):
                for k in range(j + 1, n):
                    if low <= values[i] + values[j] + values[k] <= high:
                        count += 1
        return count

