class Solution {
    public long countTriplesInBand(int[] values, int low, int high) {
        int n = values.length;
        long count = 0;
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                for (int k = j + 1; k < n; k++) {
                    int s = values[i] + values[j] + values[k];
                    if (low <= s && s <= high) count++;
                }
        return count;
    }
}

