class Solution:
    def countTriplesInBand(self, values: List[int], low: int, high: int) -> int:
        a = sorted(values)
        def at_most(x):
            total = 0
            for i in range(len(a) - 2):
                j, k = i + 1, len(a) - 1
                while j < k:
                    if a[i] + a[j] + a[k] <= x:
                        total += k - j
                        j += 1
                    else:
                        k -= 1
            return total
        return at_most(high) - at_most(low - 1)

