class Solution {
    private int[] a;

    private long atMost(int x) {
        long total = 0;
        for (int i = 0; i + 2 < a.length; i++) {
            int j = i + 1, k = a.length - 1;
            while (j < k) {
                if (a[i] + a[j] + a[k] <= x) { total += k - j; j++; }
                else k--;
            }
        }
        return total;
    }

    public long countTriplesInBand(int[] values, int low, int high) {
        a = values.clone();
        Arrays.sort(a);
        return atMost(high) - atMost(low - 1);
    }
}

