static int cmp_int(const void* x, const void* y) {
    int a = *(const int*) x, b = *(const int*) y;
    return (a > b) - (a < b);
}

static long long at_most(const int* a, int n, int x) {
    long long total = 0;
    for (int i = 0; i + 2 < n; i++) {
        int j = i + 1, k = n - 1;
        while (j < k) {
            if (a[i] + a[j] + a[k] <= x) { total += k - j; j++; }
            else k--;
        }
    }
    return total;
}

long long countTriplesInBand(int* values, int valuesSize, int low, int high) {
    int* a = malloc(valuesSize * sizeof(int));
    memcpy(a, values, valuesSize * sizeof(int));
    qsort(a, valuesSize, sizeof(int), cmp_int);
    long long answer = at_most(a, valuesSize, high) - at_most(a, valuesSize, low - 1);
    free(a);
    return answer;
}
